CREATE TABLE t_p2751751_quantum_rush.users (id SERIAL PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, display_name VARCHAR(100) NOT NULL, phone VARCHAR(20) UNIQUE, email VARCHAR(255) UNIQUE, password_hash VARCHAR(255) NOT NULL, avatar_color VARCHAR(20) DEFAULT '#5865f2', avatar_letter VARCHAR(5) DEFAULT 'U', is_admin BOOLEAN DEFAULT FALSE, is_online BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT NOW());